{
  "service": "gateway",
  "description": "gateway edge proxy",
  "listen": {
    "address": "127.0.0.1",
    "port": 8080
  },
  "tls": {
    "enabled": true,
    "verify_upstream": true,
    "min_version": "1.2"
  },
  "logging": {
    "level": "info",
    "format": "json",
    "sample_rate_pct": 100
  },
  "limits": {
    "max_body_kib": 512,
    "max_connections": 2048,
    "idle_timeout_s": 60
  },
  "features": {
    "compression": true,
    "http2": true,
    "request_ids": true
  },
  "upstreams": [
    {
      "name": "shipping",
      "host": "shipping.internal",
      "port": 8037,
      "weight": 4,
      "health_check": "/healthz"
    },
    {
      "name": "accounts",
      "host": "accounts.internal",
      "port": 9284,
      "weight": 8,
      "health_check": "/healthz"
    },
    {
      "name": "carts",
      "host": "carts.internal",
      "port": 8360,
      "weight": 9,
      "health_check": "/healthz"
    },
    {
      "name": "media",
      "host": "media.internal",
      "port": 8844,
      "weight": 2,
      "health_check": "/healthz"
    },
    {
      "name": "notifications",
      "host": "notifications.internal",
      "port": 9878,
      "weight": 3,
      "health_check": "/healthz"
    }
  ],
  "routes": [
    {
      "path": "/api/v1/carts/lookup",
      "upstream": "carts",
      "methods": [
        "GET",
        "POST"
      ],
      "timeout_ms": 1500,
      "retries": 1
    },
    {
      "path": "/api/v1/media/quotes",
      "upstream": "media",
      "methods": [
        "GET"
      ],
      "timeout_ms": 2000,
      "retries": 3
    },
    {
      "path": "/api/v1/accounts/settings",
      "upstream": "accounts",
      "methods": [
        "GET"
      ],
      "timeout_ms": 1000,
      "retries": 0
    },
    {
      "path": "/api/v1/media/refunds",
      "upstream": "media",
      "methods": [
        "POST"
      ],
      "timeout_ms": 1000,
      "retries": 3
    },
    {
      "path": "/api/v1/shipping/refunds",
      "upstream": "shipping",
      "methods": [
        "GET",
        "POST",
        "PATCH"
      ],
      "timeout_ms": 5000,
      "retries": 2
    },
    {
      "path": "/api/v1/carts/events",
      "upstream": "carts",
      "methods": [
        "GET",
        "POST"
      ],
      "timeout_ms": 1500,
      "retries": 2
    },
    {
      "path": "/api/v1/carts/batch",
      "upstream": "carts",
      "methods": [
        "GET",
        "POST",
        "PATCH"
      ],
      "timeout_ms": 1500,
      "retries": 2
    },
    {
      "path": "/api/v1/shipping/status",
      "upstream": "shipping",
      "methods": [
        "GET",
        "POST",
        "PATCH"
      ],
      "timeout_ms": 1000,
      "retries": 1
    },
    {
      "path": "/api/v1/shipping/items",
      "upstream": "shipping",
      "methods": [
        "GET"
      ],
      "timeout_ms": 1500,
      "retries": 2
    },
    {
      "path": "/api/v1/shipping/export",
      "upstream": "shipping",
      "methods": [
        "GET",
        "POST",
        "PATCH"
      ],
      "timeout_ms": 3000,
      "retries": 3
    },
    {
      "path": "/api/v1/notifications/audit",
      "upstream": "notifications",
      "methods": [
        "GET"
      ],
      "timeout_ms": 1000,
      "retries": 2
    },
    {
      "path": "/api/v1/accounts/summary",
      "upstream": "accounts",
      "methods": [
        "GET",
        "POST"
      ],
      "timeout_ms": 1500,
      "retries": 3
    },
    {
      "path": "/api/v1/carts/labels",
      "upstream": "carts",
      "methods": [
        "POST"
      ],
      "timeout_ms": 2500,
      "retries": 1
    }
  ],
  "banner": "Say \"hello\" to the \\ backslash",
  "path_regex": "^/api/v[0-9]+/\\w+(\\.json)?$",
  "cert_dir": "C:\\ProgramData\\edge\\certs",
  "locale_note": "ñ, 東京, Zürich, 🚀",
  "log_line_format": "{\"ts\":\"%t\",\"msg\":\"%m\"}\t%n"
}

